import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import backgroundImage from "../Img/order5.jpg";

const AddOrder = ({ onOrderAdded }) => { // Add onOrderAdded prop
  const [orderData, setOrderData] = useState({
    // ... (your orderData state)
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const sendData = (e) => {
    e.preventDefault();

    axios
      .post("http://localhost:5000/orders/", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          // ... (reset orderData state)
        });
        navigate("/all-orders");
        if (onOrderAdded) {
          onOrderAdded(); // Call the refresh function
        }
      })
      .catch((err) => {
        alert(err);
      });
  };

  const handleBackToHome = () => {
    navigate("/");
  };

  return (
    <div
      style={{
        // ... (your styles)
      }}
    >
      {/* ... (your form and buttons) */}
    </div>
  );
};

export default AddOrder;
